package com.auth.service

import java.security.SecureRandom
import java.time.Instant
import java.time.Duration
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import org.mindrot.jbcrypt.BCrypt

data class AuditEvent(
    val timestamp: Instant,
    val username: String,
    val ipAddress: String,
    val eventType: String,
    val success: Boolean,
    val metadata: Map<String, String> = emptyMap()
)

data class UserRecord(
    val username: String,
    val passwordHash: String,
    val locked: Boolean = false,
    val lockUntil: Instant? = null
)

data class RateLimitEntry(
    val attempts: AtomicInteger = AtomicInteger(0),
    val windowStart: Instant = Instant.now(),
    val lockedUntil: Instant? = null
)

class AuditLogger {
    private val events = mutableListOf<AuditEvent>()

    fun log(event: AuditEvent) {
        synchronized(events) {
            events.add(event)
        }
    }

    fun getRecentEvents(username: String, since: Instant): List<AuditEvent> {
        synchronized(events) {
            return events.filter { it.username == username && it.timestamp.isAfter(since) }
        }
    }
}

class AuthenticationService(
    private val userRepository: ConcurrentHashMap<String, UserRecord> = ConcurrentHashMap(),
    private val auditLogger: AuditLogger = AuditLogger(),
    private val rateLimitWindow: Duration = Duration.ofMinutes(15),
    private val maxAttemptsPerWindow: Int = 5,
    private val lockoutDuration: Duration = Duration.ofMinutes(30)
) {
    private val ipRateLimits = ConcurrentHashMap<String, RateLimitEntry>()
    private val userRateLimits = ConcurrentHashMap<String, RateLimitEntry>()
    private val secureRandom = SecureRandom()

    fun registerUser(username: String, password: String): Boolean {
        val hash = BCrypt.hashpw(password, BCrypt.gensalt(12))
        val record = UserRecord(username = username, passwordHash = hash)
        return userRepository.putIfAbsent(username, record) == null
    }

    fun authenticate(username: String, password: String, ipAddress: String): AuthResult {
        // Check IP-based rate limiting
        val ipLimitResult = checkIpRateLimit(ipAddress)
        if (ipLimitResult != null) {
            auditLogger.log(AuditEvent(
                timestamp = Instant.now(),
                username = username,
                ipAddress = ipAddress,
                eventType = "AUTH_RATE_LIMITED_IP",
                success = false,
                metadata = mapOf("reason" to "ip_rate_limit")
            ))
            return ipLimitResult
        }

        // Check user-based rate limiting
        val userLimitResult = checkUserRateLimit(username)
        if (userLimitResult != null) {
            auditLogger.log(AuditEvent(
                timestamp = Instant.now(),
                username = username,
                ipAddress = ipAddress,
                eventType = "AUTH_RATE_LIMITED_USER",
                success = false,
                metadata = mapOf("reason" to "user_rate_limit")
            ))
            return userLimitResult
        }

        val user = userRepository[username]

        // Constant-time comparison even for non-existent users
        val dummyHash = "\$2a\$12\$LJ3m4sMKfRzb3Z5K3Z5K3OdummyhashvalueforTimingProtection"
        val hashToCheck = user?.passwordHash ?: dummyHash
        val passwordValid = BCrypt.checkpw(password, hashToCheck)

        if (user == null) {
            recordFailedAttempt(username, ipAddress)
            auditLogger.log(AuditEvent(
                timestamp = Instant.now(),
                username = username,
                ipAddress = ipAddress,
                eventType = "AUTH_FAILED_NO_USER",
                success = false
            ))
            return AuthResult.Failed("Invalid credentials")
        }

        if (user.locked && user.lockUntil?.isAfter(Instant.now()) == true) {
            recordFailedAttempt(username, ipAddress)
            auditLogger.log(AuditEvent(
                timestamp = Instant.now(),
                username = username,
                ipAddress = ipAddress,
                eventType = "AUTH_ACCOUNT_LOCKED",
                success = false
            ))
            return AuthResult.AccountLocked(user.lockUntil)
        }

        if (!passwordValid) {
            recordFailedAttempt(username, ipAddress)
            val failCount = getUserFailCount(username)
            if (failCount >= maxAttemptsPerWindow) {
                lockAccount(username)
            }
            auditLogger.log(AuditEvent(
                timestamp = Instant.now(),
                username = username,
                ipAddress = ipAddress,
                eventType = "AUTH_FAILED_BAD_PASSWORD",
                success = false,
                metadata = mapOf("attemptCount" to failCount.toString())
            ))
            return AuthResult.Failed("Invalid credentials")
        }

        // Success - reset counters
        resetUserRateLimit(username)
        auditLogger.log(AuditEvent(
            timestamp = Instant.now(),
            username = username,
            ipAddress = ipAddress,
            eventType = "AUTH_SUCCESS",
            success = true
        ))
        return AuthResult.Success(generateSessionToken())
    }

    private fun checkIpRateLimit(ipAddress: String): AuthResult? {
        val entry = ipRateLimits.computeIfAbsent(ipAddress) { RateLimitEntry() }
        val now = Instant.now()

        if (entry.lockedUntil != null && now.isBefore(entry.lockedUntil)) {
            return AuthResult.RateLimited(entry.lockedUntil)
        }

        if (Duration.between(entry.windowStart, now) > rateLimitWindow) {
            ipRateLimits[ipAddress] = RateLimitEntry()
            return null
        }

        if (entry.attempts.get() >= maxAttemptsPerWindow * 3) {
            val lockUntil = now.plus(lockoutDuration)
            ipRateLimits[ipAddress] = RateLimitEntry(lockedUntil = lockUntil)
            return AuthResult.RateLimited(lockUntil)
        }

        return null
    }

    private fun checkUserRateLimit(username: String): AuthResult? {
        val entry = userRateLimits.computeIfAbsent(username) { RateLimitEntry() }
        val now = Instant.now()

        if (entry.lockedUntil != null && now.isBefore(entry.lockedUntil)) {
            return AuthResult.RateLimited(entry.lockedUntil)
        }

        if (Duration.between(entry.windowStart, now) > rateLimitWindow) {
            userRateLimits[username] = RateLimitEntry()
            return null
        }

        if (entry.attempts.get() >= maxAttemptsPerWindow) {
            val lockUntil = now.plus(lockoutDuration)
            userRateLimits[username] = RateLimitEntry(lockedUntil = lockUntil)
            return AuthResult.RateLimited(lockUntil)
        }

        return null
    }

    private fun recordFailedAttempt(username: String, ipAddress: String) {
        ipRateLimits.computeIfAbsent(ipAddress) { RateLimitEntry() }.attempts.incrementAndGet()
        userRateLimits.computeIfAbsent(username) { RateLimitEntry() }.attempts.incrementAndGet()
    }

    private fun getUserFailCount(username: String): Int {
        return userRateLimits[username]?.attempts?.get() ?: 0
    }

    private fun resetUserRateLimit(username: String) {
        userRateLimits.remove(username)
    }

    private fun lockAccount(username: String) {
        val user = userRepository[username] ?: return
        val lockUntil = Instant.now().plus(lockoutDuration)
        userRepository[username] = user.copy(locked = true, lockUntil = lockUntil)
    }

    private fun generateSessionToken(): String {
        val bytes = ByteArray(32)
        secureRandom.nextBytes(bytes)
        return bytes.joinToString("") { "%02x".format(it) }
    }
}

sealed class AuthResult {
    data class Success(val token: String) : AuthResult()
    data class Failed(val message: String) : AuthResult()
    data class AccountLocked(val until: Instant) : AuthResult()
    data class RateLimited(val until: Instant) : AuthResult()
}
